"use strict";

/**
 * Shared core of the Murmur visualizers. It has no dependencies and builds
 * every node with DOM APIs (never from strings), so a flight log from any
 * source cannot inject markup.
 *
 * The visualizer (index.html) consumes the JSON flight log generated by the
 * compiler.
 */
const Murmur = (() => {
	const SVG = "http://www.w3.org/2000/svg";

	/** Flight phases and maneuvers, as shown to the operator. */
	const PHASES = { ground: "En tierra", climb: "Ascenso", cruise: "Tránsito", hover: "Estacionario", descent: "Descenso" };
	const MANEUVERS = { takeoff: "Despegue", land: "Aterrizaje", morph: "Cambio de formación", sweep: "Barrido", orbit: "Órbita", hold: "Espera", return: "Retorno" };
	const FLEET_SLOTS = 8;

	/* DOM HELPERS */

	/** Creates an HTML element. Children are nodes or plain text. */
	function h(tag, props = {}, ...children) {
		const node = document.createElement(tag);
		for (const [key, value] of Object.entries(props || {})) {
			if (value === null || value === undefined || value === false) continue;
			if (key === "class") node.className = value;
			else if (key === "style") node.setAttribute("style", value);
			else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
			else node.setAttribute(key, value === true ? "" : value);
		}
		for (const child of children.flat()) {
			if (child === null || child === undefined || child === false) continue;
			node.appendChild(child instanceof Node ? child : document.createTextNode(String(child)));
		}
		return node;
	}

	/** Creates an SVG element. */
	function s(tag, attrs = {}, parent, text) {
		const node = document.createElementNS(SVG, tag);
		for (const [key, value] of Object.entries(attrs)) {
			if (value !== null && value !== undefined) node.setAttribute(key, value);
		}
		if (text !== undefined) node.textContent = String(text);
		if (parent) parent.appendChild(node);
		return node;
	}

	function clear(node) {
		while (node.firstChild) node.removeChild(node.firstChild);
		return node;
	}

	/* FORMATTERS */

	function num(value, digits = 0) {
		if (value === null || value === undefined || !isFinite(value)) return "—";
		return Number(value).toLocaleString("es-AR", { minimumFractionDigits: digits, maximumFractionDigits: digits });
	}
	const meters = (v, d = 0) => (v === null || v === undefined ? "—" : `${num(v, d)}\u00a0m`);
	const percent = (ratio, d = 0) => (ratio === null || ratio === undefined ? "—" : `${num(ratio * 100, d)}\u00a0%`);
	const seconds = (v, d = 0) => (v === null || v === undefined ? "—" : `${num(v, d)}\u00a0s`);
	const degrees = (rad) => (rad === null || rad === undefined ? "—" : `${num(rad * 180 / Math.PI, 0)}°`);

	/** Seconds as mm:ss. */
	function clock(t) {
		const total = Math.max(0, Math.round(t));
		return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`;
	}

	/** Duration as "14 min 50 s". */
	function duration(t) {
		if (t === null || t === undefined) return "—";
		const total = Math.round(t);
		const m = Math.floor(total / 60);
		return m === 0 ? `${total} s` : `${m} min ${String(total % 60).padStart(2, "0")} s`;
	}

	/* MODEL */

	/**
	 * Validates a flight log and derives everything the views need: one track
	 * per aircraft (parallel arrays), speeds, the minimum separation between
	 * airborne aircraft at each instant, and mission totals.
	 */
	function prepare(log) {
		if (!log || log.format !== "murmur-flight-log" || !log.timeline || !Array.isArray(log.timeline.frames)) {
			throw new Error("El archivo no es un plan de vuelo de Murmur (falta \"format\": \"murmur-flight-log\").");
		}
		const frames = log.timeline.frames;
		const fleets = log.fleets || [];
		const types = Object.fromEntries((log.droneTypes || []).map((type) => [type.name, type]));
		const fleetIndex = {};
		fleets.forEach((fleet, k) => (fleet.aircraft || []).forEach((id) => { fleetIndex[id] = k; }));

		const tracks = {};
		for (const frame of frames) {
			for (const d of frame.drones || []) {
				const track = tracks[d.id] || (tracks[d.id] = { t: [], x: [], y: [], z: [], phase: [], battery: [], speed: [] });
				const n = track.t.length;
				let speed = 0;
				if (n > 0 && frame.t > track.t[n - 1]) {
					speed = Math.hypot(d.x - track.x[n - 1], d.y - track.y[n - 1], d.z - track.z[n - 1]) / (frame.t - track.t[n - 1]);
				}
				track.t.push(frame.t); track.x.push(d.x); track.y.push(d.y); track.z.push(d.z);
				track.phase.push(d.phase); track.battery.push(d.battery); track.speed.push(speed);
			}
		}

		const aircraft = (log.aircraft || []).map((a) => ({
			...a,
			fleetIndex: fleetIndex[a.id] ?? 0,
			slot: (fleetIndex[a.id] ?? 0) % FLEET_SLOTS + 1,
			spec: types[a.type] || null,
			track: tracks[a.id] || null,
			maxAltitude: tracks[a.id] ? Math.max(...tracks[a.id].z) : null,
			maxSpeed: tracks[a.id] ? Math.max(...tracks[a.id].speed) : null,
		}));

		// Minimum distance between every pair of airborne aircraft, per frame.
		const separation = frames.map((frame) => {
			const flying = (frame.drones || []).filter((d) => d.phase !== "ground");
			let best = null;
			for (let i = 0; i < flying.length; ++i) {
				for (let j = i + 1; j < flying.length; ++j) {
					const d = Math.hypot(flying[i].x - flying[j].x, flying[i].y - flying[j].y, flying[i].z - flying[j].z);
					if (best === null || d < best.d) best = { d, a: flying[i].id, b: flying[j].id };
				}
			}
			return { t: frame.t, ...(best || { d: null, a: null, b: null }) };
		});
		const closest = separation.reduce((min, p) => (p.d !== null && (min === null || p.d < min.d) ? p : min), null);

		const maneuvers = (log.phases || []).filter((p) => p.maneuver !== "sequence" && p.maneuver !== "parallel").map((p) => ({
			...p,
			group: String(p.label).split(" ")[0],
			name: MANEUVERS[p.maneuver] || p.maneuver,
			target: String(p.label).split(" ").slice(2).join(" ").replace(/^to /, ""),
		}));

		const deployed = aircraft.filter((a) => a.deployed && a.track);
		const t0 = frames.length ? frames[0].t : 0;
		const t1 = frames.length ? frames[frames.length - 1].t : 0;
		const constraints = log.constraints || { minSeparation: null, batteryReserve: null, coverage: [] };
		return {
			log, frames, fleets, types, tracks, aircraft, deployed, separation, closest, maneuvers, constraints,
			mission: log.mission || null,
			zones: log.zones || [],
			stations: log.stations || [],
			t0, t1,
			totals: {
				distance: deployed.reduce((sum, a) => sum + (a.distance || 0), 0),
				lowestBattery: deployed.reduce((min, a) => (min === null || a.batteryAtEnd < min.batteryAtEnd ? a : min), null),
				maxAltitude: deployed.reduce((max, a) => Math.max(max, a.maxAltitude || 0), 0),
			},
		};
	}

	/** Linear interpolation of the state of an aircraft at instant t. */
	function sample(track, t) {
		if (!track || track.t.length === 0 || t < track.t[0]) return null;
		const last = track.t.length - 1;
		let lo = 0;
		let hi = last;
		if (t >= track.t[last]) lo = hi = last;
		while (lo + 1 < hi) {
			const mid = (lo + hi) >> 1;
			if (track.t[mid] <= t) lo = mid; else hi = mid;
		}
		const span = track.t[hi] - track.t[lo];
		const u = span > 0 ? (t - track.t[lo]) / span : 0;
		const mix = (array) => array[lo] + u * (array[hi] - array[lo]);
		return { index: lo, x: mix(track.x), y: mix(track.y), z: mix(track.z), battery: mix(track.battery), speed: track.speed[hi], phase: track.phase[u > 0 ? hi : lo] };
	}

	/** Maneuvers in execution at instant t. */
	function activeManeuvers(model, t) {
		return model.maneuvers.filter((m) => m.start <= t && t <= m.end);
	}

	/* PLAYBACK */

	class Player {
		constructor(t0, t1) {
			this.t0 = t0; this.t1 = t1; this.t = t0;
			this.playing = false; this.rate = 20; this.listeners = [];
			this._tick = this._tick.bind(this);
		}
		on(listener) { this.listeners.push(listener); return this; }
		emit() { for (const listener of this.listeners) listener(this.t, this); }
		seek(t) { this.t = Math.min(this.t1, Math.max(this.t0, t)); this.emit(); }
		toggle() {
			this.playing = !this.playing;
			if (this.playing) {
				if (this.t >= this.t1) this.t = this.t0;
				this._last = performance.now();
				requestAnimationFrame(this._tick);
			}
			this.emit();
		}
		_tick(now) {
			if (!this.playing) return;
			this.t = Math.min(this.t1, this.t + (now - this._last) / 1000 * this.rate);
			this._last = now;
			if (this.t >= this.t1) this.playing = false;
			this.emit();
			if (this.playing) requestAnimationFrame(this._tick);
		}
	}

	/**
	 * Play button, scrubber, clock and speed selector, bound to a player.
	 * Several transports can share a player; only the one created with
	 * keys = true answers to the space bar.
	 */
	function transport(player, { keys = true } = {}) {
		const play = h("button", { class: "mm-play", type: "button", "aria-label": "Reproducir" }, "▶");
		const range = h("input", { class: "mm-range", type: "range", min: player.t0, max: player.t1, step: "0.5", value: player.t0, "aria-label": "Instante de la misión" });
		const time = h("output", { class: "mm-clock" });
		const rate = h("select", { class: "mm-rate", "aria-label": "Velocidad de reproducción" },
			[1, 5, 20, 60].map((r) => h("option", { value: r, selected: r === player.rate }, `${r}×`)));
		play.addEventListener("click", () => player.toggle());
		range.addEventListener("input", () => player.seek(Number(range.value)));
		rate.addEventListener("change", () => { player.rate = Number(rate.value); player.emit(); });
		player.on((t) => {
			play.textContent = player.playing ? "❚❚" : "▶";
			play.setAttribute("aria-label", player.playing ? "Pausar" : "Reproducir");
			range.value = t;
			rate.value = player.rate;
			time.textContent = `${clock(t)}  (t = ${num(t, 0)} s)`;
		});
		if (keys) document.addEventListener("keydown", (event) => {
			if (event.code === "Space" && !/^(INPUT|SELECT|BUTTON|TEXTAREA)$/.test(event.target.tagName)) {
				event.preventDefault();
				player.toggle();
			}
		});
		return h("div", { class: "mm-transport" }, play, range, time, h("label", { class: "mm-rate-label" }, "Velocidad ", rate));
	}

	/* MAP */

	/**
	 * Draws the mission on an SVG: grid, zones, stations and aircraft. To keep
	 * the picture readable, routes are shown on demand:
	 *  - route "tail" (default): each aircraft only drags the trail of its last
	 *    seconds, fading out;
	 *  - route "full": the whole route of every aircraft;
	 *  - a selected aircraft always shows its whole route, with arrows that
	 *    indicate the direction of travel (solid = already flown, dashed =
	 *    still ahead), while the others are dimmed.
	 * The "swath" option paints the ground already seen by each sensor: the
	 * disk of radius altitude * tan(fov / 2) swept along the route flown so
	 * far, the same geometry the compiler uses to compute zone coverage. The
	 * ground keeps the color of the last aircraft that flew over it, and the
	 * stretch of the last "tail" seconds is stronger and fades out.
	 * Colors come from CSS custom properties, so each view themes the same map.
	 */
	class MapView {
		constructor(svg, model, options = {}) {
			this.svg = clear(svg);
			this.model = model;
			// "only" restricts the map to a single aircraft (used for small multiples).
			this.options = { route: "tail", tail: 90, footprint: false, swath: true, labels: true, selected: null, only: null, onSelect: null, ...options };
			const b = this.bounds = this._bounds();
			const w = b.maxX - b.minX;
			const hgt = b.maxY - b.minY;
			const u = this.unit = Math.max(w, hgt) / 640;
			svg.setAttribute("viewBox", `${b.minX} ${-b.maxY} ${w} ${hgt}`);
			svg.setAttribute("role", "img");
			svg.setAttribute("aria-label", "Mapa de la misión: zonas, estaciones y aeronaves");

			const defs = s("defs", {}, svg);
			// Everything painted on the ground is clipped to the map frame.
			const clipId = `mm-clip-${++MapView.count}`;
			s("rect", { x: b.minX, y: -b.maxY, width: w, height: hgt }, s("clipPath", { id: clipId }, defs));
			const hatch = s("pattern", { id: "mm-hatch", width: 7 * u, height: 7 * u, patternUnits: "userSpaceOnUse", patternTransform: "rotate(45)" }, defs);
			s("line", { x1: 0, y1: 0, x2: 0, y2: 7 * u, style: "stroke: var(--excluded)", "stroke-opacity": 0.55, "stroke-width": 1.4 * u }, hatch);

			// Grid with a "nice" step, labeled in meters.
			const step = this.step = niceStep(Math.max(w, hgt) / 6);
			const grid = s("g", { style: "stroke: var(--map-grid)", "stroke-width": u }, svg);
			const ticks = s("g", { style: "fill: var(--map-muted)", "font-size": 10 * u }, svg);
			for (let x = Math.ceil(b.minX / step) * step; x <= b.maxX; x += step) {
				s("line", { x1: x, y1: -b.maxY, x2: x, y2: -b.minY }, grid);
				s("text", { x: x + 3 * u, y: -b.minY - 4 * u }, ticks, `${num(x)} m`);
			}
			for (let y = Math.ceil(b.minY / step) * step; y <= b.maxY; y += step) {
				s("line", { x1: b.minX, y1: -y, x2: b.maxX, y2: -y }, grid);
				s("text", { x: b.minX + 3 * u, y: -y - 3 * u }, ticks, `${num(y)} m`);
			}

			const halo = `paint-order: stroke; stroke: var(--map-surface); stroke-width: ${3 * u}px`;
			const zones = s("g", {}, svg);
			for (const zone of model.zones) {
				const points = zone.vertices.map(([x, y]) => `${x},${-y}`).join(" ");
				const color = zone.excluded ? "var(--excluded)" : "var(--zone)";
				s("polygon", {
					points,
					style: `fill: ${zone.excluded ? "url(#mm-hatch)" : color}; fill-opacity: ${zone.excluded ? 1 : zone.swept ? 0.07 : 0}; stroke: ${color}`,
					"stroke-width": 1.2 * u,
					"stroke-dasharray": zone.swept || zone.excluded ? null : `${5 * u} ${4 * u}`,
				}, zones);
				const top = Math.max(...zone.vertices.map(([, y]) => y));
				s("text", { x: zone.center[0], y: -top - 6 * u, "font-size": 11.5 * u, "text-anchor": "middle", style: `fill: var(--map-ink); fill-opacity: .75; ${halo}` }, zones, zone.name + (zone.excluded ? " (excluida)" : ""));
			}
			for (const station of model.stations) {
				const [x, y] = station.position;
				s("path", { d: `M ${x} ${-y - 7 * u} L ${x + 7 * u} ${-y} L ${x} ${-y + 7 * u} L ${x - 7 * u} ${-y} Z`, style: "fill: var(--map-ink); stroke: var(--map-surface)", "stroke-width": 1.5 * u }, zones);
				s("text", { x: x + 11 * u, y: -y + 16 * u, "font-size": 11 * u, style: `fill: var(--map-ink); ${halo}` }, zones, station.name);
			}

			// Swath: a single translucent layer in which every stretch is painted
			// opaque and in chronological order, so overlapping passes do not get
			// darker and the ground keeps the color of the last one. On top, the
			// recent stretch of each aircraft, fading out with its age.
			const ground = { fill: "none", "stroke-linejoin": "round", "stroke-linecap": "round", "clip-path": `url(#${clipId})` };
			const swathLayer = s("g", { ...ground, opacity: MapView.SWATH_OPACITY }, svg);
			const recentLayer = s("g", ground, svg);
			this.footLayer = s("g", {}, svg);
			const routes = s("g", { fill: "none", "stroke-linejoin": "round", "stroke-linecap": "round" }, svg);
			const markers = s("g", {}, svg);
			this.items = model.deployed.map((a) => {
				const color = `var(--fleet-${a.slot})`;
				const track = a.track;
				const all = track.x.map((x, k) => `${x},${-track.y[k]}`).join(" ");
				const group = s("g", { class: "mm-map-item" }, routes);
				const ahead = s("polyline", { points: all, style: `stroke: ${color}`, "stroke-width": 1.2 * u, "stroke-dasharray": `${2 * u} ${5 * u}` }, group);
				const done = s("polyline", { style: `stroke: ${color}`, "stroke-width": 2 * u }, group);
				const tails = [0.22, 0.5, 0.9].map((opacity) => s("polyline", { style: `stroke: ${color}`, "stroke-opacity": opacity, "stroke-width": 2 * u }, group));

				// Direction arrows along the route, and its two ends.
				const arrows = s("g", { style: `stroke: ${color}`, "stroke-width": 1.6 * u }, group);
				let walked = 0;
				let next = 30 * u;
				for (let k = 1; k < track.x.length; ++k) {
					const dx = track.x[k] - track.x[k - 1];
					const dy = track.y[k] - track.y[k - 1];
					const d = Math.hypot(dx, dy);
					walked += d;
					if (d > 1e-6 && walked >= next) {
						next = walked + 75 * u;
						const angle = Math.atan2(-dy, dx) * 180 / Math.PI;
						s("path", { d: `M ${-4 * u} ${-4 * u} L ${3 * u} 0 L ${-4 * u} ${4 * u}`, transform: `translate(${track.x[k]} ${-track.y[k]}) rotate(${angle})` }, arrows);
					}
				}
				const last = track.x.length - 1;
				const ends = s("g", { "font-size": 10 * u, style: `fill: var(--map-ink); ${halo}` }, group);
				s("text", { x: track.x[0] - 8 * u, y: -track.y[0] - 10 * u, "text-anchor": "end" }, ends, "despega");
				if (Math.hypot(track.x[last] - track.x[0], track.y[last] - track.y[0]) > 30 * u) {
					s("text", { x: track.x[last] + 8 * u, y: -track.y[last] - 10 * u }, ends, "aterriza");
				}

				const g = s("g", { class: "mm-map-item" }, markers);
				s("circle", { r: 13 * u, fill: "transparent" }, g);
				const nose = s("path", { d: `M ${10.5 * u} 0 L ${4 * u} ${-4 * u} L ${4 * u} ${4 * u} Z`, style: `fill: ${color}` }, g);
				const dot = s("circle", { r: 5 * u, style: `fill: ${color}; stroke: var(--map-surface)`, "stroke-width": 1.8 * u }, g);
				const text = s("text", { "font-size": 10.5 * u, "font-weight": 600, style: `fill: var(--map-ink); ${halo}` }, g, a.id);
				s("title", {}, g, `${a.id} · flota ${a.fleet}`);
				const select = () => this.options.onSelect && this.options.onSelect(a.id);
				g.addEventListener("click", select);
				let swath = null;
				const halfFov = a.spec && a.spec.payload ? Math.tan(a.spec.payload.fov / 2) : 0;
				if (halfFov > 0) {
					const widths = track.z.map((z) => 2 * Math.max(z, 0) * halfFov);
					swath = {
						color, widths, halfFov, chunks: this._swathChunks(track, widths), shown: null,
						bands: MapView.FADE.map((opacity) => s("polyline", { style: `stroke: ${color}`, "stroke-opacity": opacity, "stroke-linecap": "butt" }, recentLayer)),
					};
				}
				return {
					aircraft: a, group, g, ahead, done, tails, arrows, ends, nose, dot, text, swath,
					foot: s("circle", { style: `fill: ${color}; stroke: ${color}`, "fill-opacity": 0.07, "stroke-opacity": 0.3, "stroke-width": u }, this.footLayer),
				};
			});

			const chunks = [];
			for (const item of this.items) {
				if (item.swath) item.swath.chunks.forEach((chunk) => chunks.push([chunk, item.swath.color]));
			}
			chunks.sort(([a], [b]) => a.t - b.t);
			for (const [chunk, color] of chunks) chunk.el = s("polyline", { style: `stroke: ${color}`, "stroke-width": chunk.width }, swathLayer);
		}

		/**
		 * Splits a track into short stretches flown at about the same altitude,
		 * each one drawn as a polyline as wide as the sensor footprint. They are
		 * short so that, sorted by time, the last pass over a spot is on top.
		 * Consecutive stretches share their end point to stay continuous.
		 */
		_swathChunks(track, widths) {
			const quantum = Math.max(this.unit, Math.max(...widths) / 24);
			const chunks = [];
			let chunk = null;
			for (let k = 0; k < track.t.length; ++k) {
				if (track.phase[k] === "ground" || widths[k] < this.unit) { chunk = null; continue; }
				const width = Math.max(1, Math.round(widths[k] / quantum)) * quantum;
				if (chunk === null || chunk.width !== width || track.t[k] - chunk.t >= MapView.CHUNK) {
					const from = chunk === null ? k : k - 1;
					chunk = { from, to: k, t: track.t[from], width, state: null };
					chunks.push(chunk);
				}
				chunk.to = k;
			}
			return chunks;
		}

		/** Paints the swath of an aircraft up to instant t (frame "index", then point "here"). */
		_paintSwath(swath, track, t, index, here, visible, dimmed) {
			const look = `${visible}/${dimmed}`;
			for (const chunk of swath.chunks) {
				const state = !visible || index < chunk.from ? "none" : chunk.to <= index ? "full" : "partial";
				if (state === chunk.state && state !== "partial" && look === swath.shown) continue;
				chunk.state = state;
				const points = [];
				if (state !== "none") {
					for (let k = chunk.from; k <= Math.min(chunk.to, index); ++k) points.push(`${track.x[k]},${-track.y[k]}`);
					if (state === "partial") points.push(here);
					if (points.length === 1) points.push(points[0]);
				}
				chunk.el.setAttribute("points", points.join(" "));
				chunk.el.setAttribute("stroke-opacity", dimmed ? 0.3 : 1);
			}
			swath.shown = look;

			// Recent stretch, in bands that fade out with their age. Bands are
			// contiguous (each one starts where the next one ends) and have flat
			// ends, so they never overlap and no darker spots appear.
			const span = this.options.tail / swath.bands.length;
			const first = track.t[0];
			const last = Math.min(t, track.t[track.t.length - 1]);
			swath.bands.forEach((band, k) => {
				const to = Math.min(t - k * span, last);
				const from = Math.max(to - span, first);
				const points = [];
				let width = 0;
				const add = (p) => {
					if (p.phase === "ground") return;
					const point = `${p.x},${-p.y}`;
					if (point !== points[points.length - 1]) points.push(point);
				};
				if (visible && !dimmed && index >= 0 && from < to) {
					const start = sample(track, from);
					add(start);
					for (let j = start.index + 1; j <= index && track.t[j] < to; ++j) {
						add({ x: track.x[j], y: track.y[j], phase: track.phase[j] });
						width = Math.max(width, swath.widths[j]);
					}
					add(sample(track, to));
					width = Math.max(width, 2 * Math.max(start.z, 0) * swath.halfFov);
				}
				band.setAttribute("points", points.length > 1 && width >= this.unit ? points.join(" ") : "");
				band.setAttribute("stroke-width", width);
			});
		}

		_bounds() {
			let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
			const add = (x, y) => { minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y); };
			this.model.zones.forEach((z) => z.vertices.forEach(([x, y]) => add(x, y)));
			this.model.stations.forEach((st) => add(st.position[0], st.position[1]));
			this.model.deployed.forEach((a) => {
				// The ground seen by the sensor also has to fit in the map.
				const halfFov = a.spec && a.spec.payload ? Math.tan(a.spec.payload.fov / 2) : 0;
				a.track.x.forEach((x, k) => {
					const r = a.track.phase[k] === "ground" ? 0 : Math.max(a.track.z[k], 0) * halfFov;
					add(x - r, a.track.y[k] - r);
					add(x + r, a.track.y[k] + r);
				});
			});
			if (!isFinite(minX)) { minX = minY = -100; maxX = maxY = 100; }
			const pad = Math.max(maxX - minX, maxY - minY, 20) * 0.09;
			return { minX: minX - pad, minY: minY - pad, maxX: maxX + pad, maxY: maxY + pad };
		}

		/** Moves every aircraft to its position at instant t. */
		update(t) {
			const u = this.unit;
			const { route, tail, selected, labels, footprint, swath } = this.options;
			const placed = [];	// Labels already shown, to skip the ones that would overlap.
			const order = [...this.items].sort((a, b) => (b.aircraft.id === selected) - (a.aircraft.id === selected));
			for (const item of order) {
				const track = item.aircraft.track;
				const end = track.t[track.t.length - 1];
				const state = sample(track, Math.min(t, end));
				const hidden = this.options.only !== null && item.aircraft.id !== this.options.only;
				item.group.setAttribute("display", hidden ? "none" : "");
				const isSelected = item.aircraft.id === selected;
				const dimmed = selected !== null && !isSelected;
				if (hidden) {
					item.g.setAttribute("display", "none");
					item.foot.setAttribute("display", "none");
					if (item.swath) this._paintSwath(item.swath, track, t, -1, null, false, dimmed);
					continue;
				}
				item.group.setAttribute("opacity", dimmed ? 0.22 : 1);
				item.g.setAttribute("opacity", dimmed ? 0.35 : 1);
				if (!state) {
					if (item.swath) this._paintSwath(item.swath, track, t, -1, null, false, dimmed);
					item.g.setAttribute("display", "none");
					item.foot.setAttribute("display", "none");
					item.done.setAttribute("points", "");
					item.tails.forEach((line) => line.setAttribute("points", ""));
					item.ahead.setAttribute("display", isSelected || route === "full" ? "" : "none");
					item.arrows.setAttribute("display", isSelected ? "" : "none");
					item.ends.setAttribute("display", isSelected ? "" : "none");
					continue;
				}
				item.g.removeAttribute("display");
				item.g.setAttribute("transform", `translate(${state.x} ${-state.y})`);

				// Heading: a small nose on the marker while the aircraft moves.
				const before = sample(track, Math.max(track.t[0], Math.min(t, end) - 1));
				const dx = state.x - before.x;
				const dy = state.y - before.y;
				const moving = Math.hypot(dx, dy) > 0.3;
				item.nose.setAttribute("display", moving ? "" : "none");
				if (moving) item.nose.setAttribute("transform", `rotate(${Math.atan2(-dy, dx) * 180 / Math.PI})`);
				item.dot.setAttribute("fill-opacity", state.phase === "ground" ? 0.4 : 1);

				const crowded = placed.some(([px, py]) => Math.abs(px - state.x) < 62 * u && Math.abs(py - state.y) < 13 * u);
				const labeled = labels && (isSelected || (state.phase !== "ground" && !crowded));
				if (labeled) placed.push([state.x, state.y]);
				const flip = state.x + 70 * u > this.bounds.maxX;
				item.text.setAttribute("display", labeled ? "" : "none");
				item.text.setAttribute("text-anchor", flip ? "end" : "start");
				item.text.setAttribute("x", (flip ? -9 : 9) * u);
				item.text.setAttribute("y", -8 * u);

				const payload = item.aircraft.spec && item.aircraft.spec.payload;
				const radius = payload && state.phase !== "ground" ? state.z * Math.tan(payload.fov / 2) : 0;
				item.foot.setAttribute("display", footprint && radius > 0 && !dimmed ? "" : "none");
				item.foot.setAttribute("cx", state.x);
				item.foot.setAttribute("cy", -state.y);
				item.foot.setAttribute("r", radius);

				if (item.swath) this._paintSwath(item.swath, track, t, state.index, `${state.x},${-state.y}`, swath, dimmed);

				const whole = isSelected || route === "full";
				item.ahead.setAttribute("display", whole ? "" : "none");
				item.arrows.setAttribute("display", isSelected ? "" : "none");
				item.ends.setAttribute("display", isSelected ? "" : "none");
				const point = (k) => `${track.x[k]},${-track.y[k]}`;
				const here = `${state.x},${-state.y}`;
				if (whole) {
					const points = [];
					for (let k = 0; k <= state.index; ++k) points.push(point(k));
					points.push(here);
					item.done.setAttribute("points", points.join(" "));
					item.done.setAttribute("stroke-opacity", isSelected ? 1 : 0.7);
					item.tails.forEach((line) => line.setAttribute("points", ""));
				}
				else {
					// Trail of the last "tail" seconds, in three fading stretches.
					item.done.setAttribute("points", "");
					const from = sample(track, Math.max(track.t[0], Math.min(t, end) - tail));
					const span = state.index - from.index + 1;
					item.tails.forEach((line, part) => {
						const first = from.index + Math.floor(span * part / 3);
						const lastIndex = from.index + Math.floor(span * (part + 1) / 3);
						const points = [];
						for (let k = first; k <= Math.min(lastIndex, state.index); ++k) points.push(point(k));
						if (part === 2) points.push(here);
						line.setAttribute("points", points.length > 1 ? points.join(" ") : "");
					});
				}
			}
		}
	}

	MapView.count = 0;
	MapView.CHUNK = 8;						// [s] Length of each swath stretch.
	MapView.SWATH_OPACITY = 0.16;			// Ground already seen.
	MapView.FADE = [0.32, 0.27, 0.22, 0.18, 0.14, 0.1, 0.06, 0.03];	// Extra opacity of the recent stretch, newest first.

	function niceStep(raw) {
		const power = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-9))));
		const ratio = raw / power;
		return (ratio >= 5 ? 5 : ratio >= 2 ? 2 : 1) * power;
	}

	/* MANEUVER PLAN */

	/** What a maneuver does, in plain words. */
	function describeManeuver(m) {
		switch (m.maneuver) {
			case "takeoff": return `despega de ${m.target}`;
			case "land": return `aterriza en ${m.target}`;
			case "return": return `regresa a ${m.target}`;
			case "morph": return m.target.startsWith("(") ? "cambia de formación" : `forma ${m.target}`;
			case "sweep": return `barre ${m.target}`;
			case "orbit": return `orbita ${m.target}`;
			case "hold": return "espera en el lugar";
			default: return m.name.toLowerCase();
		}
	}

	/**
	 * The plan of the mission as a list: one row per maneuver, in order of
	 * start, with who does what, a bar that shows when it happens along the
	 * mission, and its start and end. The row of a maneuver in progress is
	 * highlighted, finished ones are filled and pending ones are outlined.
	 * Clicking a row moves the mission to the start of that maneuver.
	 */
	function maneuverPlan(model, player) {
		const t0 = model.t0;
		const span = Math.max(model.t1 - t0, 1e-9);
		const pct = (t) => `${((t - t0) / span * 100).toFixed(3)}%`;
		const heads = [];
		const track = (...children) => {
			const head = h("i", { class: "mm-step-now" });
			heads.push(head);
			return h("span", { class: "mm-step-track" }, children, head);
		};
		const steps = [...model.maneuvers].sort((a, b) => a.start - b.start).map((m) => {
			const who = m.group === "all" ? "Todas" : m.group;
			const row = h("button", {
				class: "mm-step", type: "button",
				title: `${who} ${describeManeuver(m)}: de ${clock(m.start)} a ${clock(m.end)} (${duration(m.end - m.start)}). Clic para ir a su inicio.`,
				onclick: () => player.seek(m.start),
			},
				h("span", { class: "mm-step-name" }, h("b", {}, who), ` ${describeManeuver(m)}`),
				track(h("i", { class: "mm-step-bar", style: `left: ${pct(m.start)}; width: calc(${pct(m.end)} - ${pct(m.start)})` })),
				h("span", { class: "mm-step-time" }, `${clock(m.start)} a ${clock(m.end)}`));
			return { m, row };
		});
		// Time axis in whole steps of 30 s, 1, 2, 5 or 10 minutes.
		const step = [30, 60, 120, 300, 600, 1800, 3600].find((value) => span / value <= 7) || 3600;
		const ticks = [];
		for (let t = Math.ceil(t0 / step) * step; t <= model.t1 + 1e-9; t += step) {
			ticks.push(h("span", { style: `left: ${pct(t)}` }, clock(t)));
		}
		const axis = h("div", { class: "mm-step mm-step-axis" }, h("span", { class: "mm-step-name" }, "Tiempo de misión"), h("span", { class: "mm-step-track" }, ticks), h("span", { class: "mm-step-time" }, "min:seg"));
		player.on((t) => {
			for (const head of heads) head.style.left = pct(t);
			for (const { m, row } of steps) {
				row.dataset.state = t < m.start ? "pending" : t > m.end ? "done" : "active";
			}
		});
		return h("div", { class: "mm-steps" },
			h("div", { class: "mm-step mm-step-head" }, h("span", {}, "Maniobra"), h("span", {}, "Cuándo ocurre"), h("span", { class: "mm-step-time" }, "Inicio a fin")),
			steps.map((step) => step.row),
			axis,
			h("p", { class: "mm-step-key" },
				h("span", {}, h("i", { class: "mm-step-bar", "data-key": "active" }), "en curso"),
				h("span", {}, h("i", { class: "mm-step-bar", "data-key": "done" }), "terminada"),
				h("span", {}, h("i", { class: "mm-step-bar", "data-key": "pending" }), "pendiente"),
				h("span", {}, h("i", { class: "mm-step-now", "data-key": "now" }), "instante actual")));
	}

	/* LOADING */

	/**
	 * Wires the three ways of loading a flight log: a file input, drag and
	 * drop over the page, and ?src=<same-origin path> when served over HTTP.
	 */
	function loader({ input, onLog, onError }) {
		const read = (file) => {
			const reader = new FileReader();
			reader.onload = () => {
				try { onLog(prepare(JSON.parse(reader.result)), file.name); }
				catch (error) { onError(error.message); }
			};
			reader.readAsText(file);
		};
		if (input) input.addEventListener("change", () => input.files[0] && read(input.files[0]));
		document.addEventListener("dragover", (event) => event.preventDefault());
		document.addEventListener("drop", (event) => { event.preventDefault(); if (event.dataTransfer.files[0]) read(event.dataTransfer.files[0]); });
		const src = new URLSearchParams(location.search).get("src");
		if (!src) return;
		if (new URL(src, location.href).origin !== location.origin) {
			onError("Solo se pueden abrir planes de vuelo servidos desde el mismo origen.");
			return;
		}
		fetch(src).then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
			.then((log) => onLog(prepare(log), src.split("/").pop()))
			.catch((error) => onError(`No se pudo abrir ${src}: ${error.message}`));
	}

	return { PHASES, MANEUVERS, h, s, clear, num, meters, percent, seconds, degrees, clock, duration, prepare, sample, activeManeuvers, Player, transport, MapView, maneuverPlan, loader, niceStep };
})();
